const nalati='<checkouts>/shard-nalati';
const riding=await nalatiRidingRows(compileReturnProjectionV2,name=>readFileSync(nalati+'/src/'+name,'utf8'),NALATI_ECOLOGY);
const base64=bytes=>Buffer.from(bytes).toString('base64');
writeFileSync('tmp/codex-tc48/riding.json',JSON.stringify({programs:riding.programs,wasm:base64(riding.wasm),witness:base64(riding.witness)}));
const charge=await nalatiChargeRows(compileDecisionScripts,readDecisionSources(nalati+'/src'));
writeFileSync('tmp/codex-tc48/charge.json',JSON.stringify({rows:charge.rows,wasm:base64(charge.wasm)}));
const aliases=names=>Object.fromEntries(names.map(name=>[name,name]));
const registry=names=>new Map([...names].sort().map((name,i)=>[name,i+1]));
const input={id:'driftwood.returns',abi:'1.0',side:'sim',module:`blobs/wasm/${'0'.repeat(64)}.wasm`,source:'behaviour/returns.as',binding:{shard:true},pages:1,onFail:'hold',on:['signal'],tick:null,stateVersion:1,state:[],params:{},reads:['field','random','groundHeight','radial'],commands:['channel'],fields:aliases(fields),channels:aliases(channels),signals:aliases(signals)};
const registries={fields:registry(fields),channels:registry(channels),signals:registry(signals)};
const built=await compileDecisionScripts([input],registries,readDecisionSources('<checkouts>/shard-driftwood/src'),{asLineCeiling:1716});
const RETURN_PROGRAM={script:built.rows[0],bytes:''};
writeFileSync('test/fixtures/frozen/returns.json',JSON.stringify({...RETURN_PROGRAM,bytes:base64(built.blobs[0].bytes)})+'\n');

